<?php require 'auth.php';require '../includes/config.php';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $sql="INSERT INTO properties(title,description,type,listing_type,city,address,price,area,bedrooms,bathrooms,parking,image) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)";
 $s=$conn->prepare($sql);$s->bind_param("ssssssdiiiis",$_POST['title'],$_POST['description'],$_POST['type'],$_POST['listing_type'],$_POST['city'],$_POST['address'],$_POST['price'],$_POST['area'],$_POST['bedrooms'],$_POST['bathrooms'],$_POST['parking'],$_POST['image']);
 if($s->execute()){ $msg="Property added successfully."; }
}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add Property</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'header.php';?><section class="pagehero"><div class="container"><h1>Add Property</h1><p>Create a new property listing.</p></div></section><section class="section"><div class="container" style="max-width:900px"><form class="form-card" method="post"><?php if($msg):?><p class="message"><?=$msg?></p><br><?php endif;?><div class="formgrid"><div class="full"><label>Title</label><input name="title" required></div><div><label>Type</label><select name="type"><?php foreach(['House','Apartment','Villa','Commercial','Plot'] as $x)echo "<option>$x</option>";?></select></div><div><label>Listing</label><select name="listing_type"><option>Buy</option><option>Rent</option></select></div><div><label>City</label><input name="city" required></div><div><label>Address</label><input name="address"></div><div><label>Price</label><input type="number" step="0.01" name="price" required></div><div><label>Area</label><input type="number" name="area"></div><div><label>Bedrooms</label><input type="number" name="bedrooms" value="0"></div><div><label>Bathrooms</label><input type="number" name="bathrooms" value="0"></div><div><label>Parking</label><input type="number" name="parking" value="0"></div><div class="full"><label>Image URL</label><input name="image" placeholder="https://..."></div><div class="full"><label>Description</label><textarea name="description" rows="5"></textarea></div><div class="full"><button class="btn gold">Add Property</button></div></div></form></div></section><footer><div class="container"><div class="copyright">© 2026 DreamNest Admin Panel</div></div></footer></body></html>